class Solution {
  public boolean canPartitionGrid(int[][] grid) {
    if (check(grid)) return true;
    int m = grid.length, n = grid[0].length;
    int[][] t = new int[n][m];
    for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) t[j][i] = grid[i][j];
    return check(t);
  }

  private static boolean check(int[][] g) {
    int m = g.length, n = g[0].length;
    int[] top = new int[100_001], bot = new int[100_001];
    long total = 0;
    for (int[] row : g) {
      for (int v : row) {
        bot[v]++;
        total += v;
      }
    }
    long topSum = 0;
    for (int i = 0; i + 1 < m; i++) {
      for (int v : g[i]) {
        top[v]++;
        bot[v]--;
        topSum += v;
      }
      long bottomSum = total - topSum;
      if (topSum == bottomSum) return true;
      int h1 = i + 1, h2 = m - 1 - i;
      if (topSum > bottomSum) {
        long d = topSum - bottomSum;
        if (d > 100_000) continue;
        int dv = (int) d;
        if (h1 >= 2 && n >= 2) {
          if (top[dv] > 0) return true;
        } else if (h1 == 1) {
          if (g[0][0] == dv || g[0][n - 1] == dv) return true;
        } else if (g[0][0] == dv || g[h1 - 1][0] == dv) return true;
      } else {
        long d = bottomSum - topSum;
        if (d > 100_000) continue;
        int dv = (int) d;
        if (h2 >= 2 && n >= 2) {
          if (bot[dv] > 0) return true;
        } else if (h2 == 1) {
          if (g[m - 1][0] == dv || g[m - 1][n - 1] == dv) return true;
        } else if (g[i + 1][0] == dv || g[m - 1][0] == dv) return true;
      }
    }
    return false;
  }
}
